
local Players = game:GetService("Players")
local RealInstance = Instance

local Effects = {
	Version = 1,
	List = {},       -- ordered list of Info tables
	Map = {},        -- Name -> Info
	Active = {},     -- Name -> { Character, Objects }
}

local function Register(Name, Display, Category, Build)
	local Info = { Name = Name, Display = Display, Category = Category, Build = Build }
	table.insert(Effects.List, Info)
	Effects.Map[Name] = Info
end

----------------------------------------------------------------
-- API
----------------------------------------------------------------

local function Track(Objects)
	return {
		new = function(ClassName, Parent)
			local Object = RealInstance.new(ClassName)
			table.insert(Objects, Object)
			if Parent then
				Object.Parent = Parent
			end
			return Object
		end,
	}
end

local function DestroyAll(Objects)
	for Index = #Objects, 1, -1 do
		local Object = Objects[Index]
		pcall(function()
			Object:Destroy()
		end)
		Objects[Index] = nil
	end
end

function Effects:Has(Name)
	return self.Map[Name] ~= nil
end

function Effects:GetInfo(Name)
	local Info = self.Map[Name]
	if not Info then
		return nil
	end
	return { Name = Info.Name, Display = Info.Display, Category = Info.Category }
end

function Effects:GetCategories()
	local Seen, Result = {}, {}
	for _, Info in ipairs(self.List) do
		if not Seen[Info.Category] then
			Seen[Info.Category] = true
			table.insert(Result, Info.Category)
		end
	end
	table.sort(Result, function(A, B)
		if A == "Misc" then return false end
		if B == "Misc" then return true end
		return A < B
	end)
	return Result
end

function Effects:GetNames(Category)
	local Result = {}
	for _, Info in ipairs(self.List) do
		if Info.Name ~= "Nothing" and (not Category or Info.Category == Category) then
			table.insert(Result, Info.Name)
		end
	end
	return Result
end

function Effects:IsActive(Name)
	return self.Active[Name] ~= nil
end

function Effects:GetActive()
	local Result = {}
	for Name in pairs(self.Active) do
		table.insert(Result, Name)
	end
	table.sort(Result)
	return Result
end

function Effects:Remove(Name)
	local State = self.Active[Name]
	if not State then
		return false
	end
	self.Active[Name] = nil
	DestroyAll(State.Objects)
	return true
end

function Effects:Clear()
	for Name in pairs(table.clone(self.Active)) do
		self:Remove(Name)
	end
end

function Effects:Apply(Name, Character)
	local Info = self.Map[Name]
	if not Info then
		return false, "Unknown effect: " .. tostring(Name)
	end

	self:Remove(Name)

	local Player = Players.LocalPlayer
	local Char = Character or Player.Character or Player.CharacterAdded:Wait()
	local Hum = Char:WaitForChild("Humanoid", 10)
	if not Hum then
		return false, "Humanoid not found"
	end

	local IsR15 = Hum.RigType == Enum.HumanoidRigType.R15
	local function L(ChildName)
		return Char:WaitForChild(ChildName, 10)
	end

	local Objects = {}
	local Success, Err = pcall(Info.Build, Player, Char, Hum, IsR15, L, Track(Objects))
	if not Success then
		DestroyAll(Objects)
		return false, tostring(Err)
	end

	self.Active[Name] = { Character = Char, Objects = Objects }
	return true
end

function Effects:Destroy()
	self:Clear()
	table.clear(self.List)
	table.clear(self.Map)
end

